import './style.css';
import { api, supabaseReady } from './api.js';
import { attendanceByClass, summarizeAttendance } from './domain.js';

const icons={home:'⌂',classes:'▦',students:'♙',attendance:'✓',absences:'◷',timetable:'▤',substitutions:'↔',statistics:'▥',reports:'▧',notifications:'♧',settings:'⚙',admin:'⌘',audit:'◉',search:'⌕',bell:'♧',menu:'☰',sun:'☼',moon:'◐'};
let user=null, data=null, page='dashboard', currentAttendance=null, attendanceDefaultClassId=null, selectedClassId=null, selectedStudentId=null, searchText='', dark=localStorage.getItem('theme')!=='light';
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>new Date(`${d}T12:00:00`).toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'Europe/Berlin'});
const dateToday=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function notify(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3000)}
async function init(){if(!supabaseReady){document.body.className='login-page';$('#app').innerHTML=`<section class="login-card"><div class="brand"><span class="brand-icon">◆</span><div><b>SchoolPresence</b><small>Supabase-Einrichtung</small></div></div><h1>Projekt verbinden</h1><p>Das Frontend ist bereit. Ergänze URL und Publishable Key deines Supabase-Projekts in der lokalen <code>.env</code> und in den GitHub Actions Secrets.</p><div class="demo-note">Erforderlich: <b>VITE_SUPABASE_URL</b><br><b>VITE_SUPABASE_PUBLISHABLE_KEY</b><br><br>Keine Secret Keys in den Browser eintragen.</div><p style="margin-top:18px">Projekt-ID: <b>bqoxpwerrrsrfdvpelnh</b></p></section>`;return}const me=await api('/me');if(!me.user)return renderLogin();user=me.user;data=await api('/bootstrap');data.sessions=await api('/attendance');data.teachers=['admin','leadership'].includes(user.role)?await api('/teachers'):[];data.rooms=await api('/rooms');render()}
function renderLogin(){document.body.className='login-page';$('#app').innerHTML=`<section class="login-card"><div class="brand"><span class="brand-icon">◆</span><div><b>SchoolPresence</b><small>Digitale Schulverwaltung</small></div></div><h1>Willkommen zurück</h1><p>Melde dich mit deinem Schulzugang an.</p><form id="login-form"><label>E-Mail-Adresse<input name="email" type="email" autocomplete="username" required placeholder="name@schule.de"></label><label>Passwort<input name="password" type="password" autocomplete="current-password" required></label><button class="primary full" type="submit">Anmelden <span>→</span></button><div id="login-error" class="error"></div></form><button class="text-button forgot-link" id="forgot-password">Passwort vergessen?</button><div class="demo-note">Zugänge werden durch die Schuladministration eingerichtet. Öffentliche Registrierung ist deaktiviert.</div></section>`;$('#login-form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await api('/login',{method:'POST',body:JSON.stringify(Object.fromEntries(fd))});location.reload()}catch(err){$('#login-error').textContent=err.message}};$('#forgot-password').onclick=()=>{dialog('Passwort zurücksetzen',`<form id="reset-form"><label>E-Mail-Adresse<input name="email" type="email" required autocomplete="email"></label><button class="primary full">Reset-Link anfordern</button></form>`);$('#reset-form').onsubmit=async e=>{e.preventDefault();try{await api('/password-reset',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeDialog();notify('Wenn das Konto existiert, wurde ein Reset-Link angefordert.')}catch(err){notify(err.message)}}}}

const nav=[['dashboard','Dashboard'],['classes','Klassen'],['students','Schüler'],['attendance','Anwesenheit'],['absences','Fehlzeiten'],['timetable','Stundenplan'],['substitutions','Vertretungsplan'],['statistics','Statistiken'],['reports','Berichte'],['notifications','Benachrichtigungen'],['settings','Einstellungen'],['admin','Administration'],['audit','Audit-Log']];
function render(){document.body.className=dark?'dark':'light';$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-icon">◆</span><div><b>SchoolPresence</b><small>Digitale Schulverwaltung</small></div><button class="mobile-close" id="close-menu">×</button></div><button class="school-switch" id="school-switch" type="button" aria-label="Schule und Schuljahr anzeigen"><span class="school-badge">${initials(data.school.name)}</span><div><b>${esc(data.school.name)}</b><small>Schuljahr ${esc(data.school.school_year)}</small></div><span>⌄</span></button><nav>${nav.map(([key,label])=>{if(user.role==='teacher'&&['admin','audit','settings'].includes(key))return '';return `<button class="nav-item ${page===key?'active':''}" data-page="${key}"><span>${icons[key]}</span>${label}</button>`}).join('')}</nav><div class="side-bottom"><button id="theme-toggle"><span>${dark?icons.sun:icons.moon}</span>${dark?'Light Mode':'Dark Mode'}<span class="toggle ${dark?'on':''}"></span></button><button class="profile" id="logout"><span class="avatar">${initials(user.name)}</span><span><b>${esc(user.name)}</b><small>${roleName(user.role)}</small></span><span class="dots">···</span></button></div></aside><main class="main"><header class="topbar"><button class="menu-button" id="open-menu">☰</button><div class="search"><span>⌕</span><input id="global-search" placeholder="Suche nach Klassen, Schülern …" value="${esc(searchText)}"><kbd>⌘ K</kbd><div id="search-results" class="search-results" hidden></div></div><div class="top-actions"><button class="icon-button" aria-label="Benachrichtigungen" data-page="notifications">♧</button><button class="user-chip" id="user-menu" type="button" aria-label="Profil und Kontoeinstellungen"><span class="avatar">${initials(user.name)}</span><span><b>${esc(user.name)}</b><small>${roleName(user.role)}</small></span><span>⌄</span></button></div></header><div id="view" class="content"></div></main><nav class="mobile-nav">${[['dashboard','Start'],['classes','Klassen'],['attendance','Anwesenheit'],['notifications','Meldungen']].map(([k,l])=>`<button data-page="${k}" class="${page===k?'active':''}"><span>${icons[k]}</span>${l}</button>`).join('')}<button id="mobile-more"><span>☰</span>Mehr</button></nav><div id="toast" class="toast" role="status"></div></div>`;
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#school-switch').onclick=()=>go('settings');$('#user-menu').onclick=()=>go('settings');$('#theme-toggle').onclick=()=>{dark=!dark;localStorage.setItem('theme',dark?'dark':'light');render()};$('#logout').onclick=async()=>{await api('/logout',{method:'POST'});location.reload()};$('#open-menu').onclick=()=>$('.sidebar').classList.add('open');$('#close-menu').onclick=()=>$('.sidebar').classList.remove('open');$('#mobile-more').onclick=()=>$('.sidebar').classList.toggle('open');$('#global-search').oninput=showSearch;$('#global-search').onfocus=showSearch;renderPage()}
function showSearch(){const box=$('#search-results'),q=$('#global-search')?.value.trim().toLowerCase();if(!box||!q||q.length<2){if(box)box.hidden=true;return}const results=[...data.classes.filter(x=>x.name.toLowerCase().includes(q)).slice(0,4).map(x=>({type:'class',id:x.id,title:`Klasse ${x.name}`,sub:`${x.student_count} Schüler/innen`})),...data.students.filter(x=>`${x.first_name} ${x.last_name} ${x.class_name}`.toLowerCase().includes(q)).slice(0,5).map(x=>({type:'student',id:x.id,title:`${x.last_name}, ${x.first_name}`,sub:`Klasse ${x.class_name}`})),...(data.sessions||[]).filter(x=>`${x.class_name} ${x.subject_name||''} ${x.session_date}`.toLowerCase().includes(q)).slice(0,3).map(x=>({type:'session',id:x.id,title:`${x.class_name} · ${x.period}. Stunde`,sub:`${fmt(x.session_date)} · ${x.subject_name||'Unterricht'}`}))];box.hidden=false;box.innerHTML=results.map(x=>`<button data-search-type="${x.type}" data-search-id="${x.id}"><b>${esc(x.title)}</b><small>${esc(x.sub)}</small></button>`).join('')||'<div class="search-empty">Keine freigegebenen Treffer.</div>';box.querySelectorAll('[data-search-id]').forEach(b=>b.onclick=()=>{box.hidden=true;$('#global-search').value='';if(b.dataset.searchType==='class'){selectedClassId=b.dataset.searchId;go('classDetail')}else if(b.dataset.searchType==='student'){selectedStudentId=b.dataset.searchId;go('studentDetail')}else{currentAttendance=b.dataset.searchId;go('attendance')}})}
function initials(n){return (n||'??').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase()}function roleName(r){return {admin:'Administrator',leadership:'Schulleitung',teacher:'Lehrkraft',student:'Schülerzugang'}[r]||r}function go(p){page=p;render()}async function refreshData(){data=await api('/bootstrap');data.sessions=await api('/attendance');data.teachers=['admin','leadership'].includes(user.role)?await api('/teachers'):[];data.rooms=await api('/rooms')}
function title(h,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">SCHOOLPRESENCE <span>·</span> ${fmt(dateToday())}</div><h1>${h}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`}
function renderPage(){const v=$('#view');if(!v)return;({dashboard:dashboard,classes:classesPage,classDetail:classDetailPage,students:studentsPage,studentDetail:studentDetailPage,attendance:attendancePage,absences:absencesPage,timetable:timetablePage,substitutions:substitutionsPage,statistics:statisticsPage,reports:reportsPage,notifications:notificationsPage,settings:settingsPage,admin:adminPage,audit:auditPage}[page]||dashboard)(v)}
function dashboard(v){const sessions=data.sessions||[];const count=data.students.length,cl=data.classes.length;const today=sessions.filter(s=>s.session_date===dateToday()).reduce((a,s)=>a+s.recorded,0);const teachers=new Set(data.classes.map(c=>c.teacher_id).filter(Boolean)).size;v.innerHTML=title(`Guten Tag, ${esc(user.name.split(' ')[0])} 👋`,'Hier ist die Übersicht deiner Schule.',`<button class="secondary" data-page="attendance">+ Anwesenheit</button>`)+`<div class="summary-banner"><div><span class="live-dot"></span> ${esc(data.school.name)} <span class="muted">· Schuljahr ${esc(data.school.school_year)}</span></div><span class="date-label">Heute, ${new Date().toLocaleDateString('de-DE',{weekday:'long',day:'numeric',month:'long',timeZone:'Europe/Berlin'})}</span></div><div class="stat-grid"><article class="stat-card blue"><div class="stat-label">Schülerinnen & Schüler <span>♙</span></div><strong>${count}</strong><small>Aktiv eingeschrieben</small></article><article class="stat-card violet"><div class="stat-label">Klassen <span>▦</span></div><strong>${cl}</strong><small>Im aktuellen Schuljahr</small></article><article class="stat-card cyan"><div class="stat-label">Zugewiesene Lehrkräfte <span>♧</span></div><strong>${teachers||'—'}</strong><small>Mit Klassenverantwortung</small></article><article class="stat-card green"><div class="stat-label">Heute erfasste Einträge <span>✓</span></div><strong>${today||'—'}</strong><small>Aus gespeicherten Listen</small></article></div><div class="dashboard-grid"><section class="panel trend-panel"><div class="panel-head"><div><h2>Anwesenheitsentwicklung</h2><p>Verlauf aus abgeschlossenen Kontrollen</p></div><select aria-label="Zeitraum"><option>Diese Woche</option><option>Dieser Monat</option></select></div><div class="chart-empty">${sessions.length?`Es gibt ${sessions.length} gespeicherte Kontrollen. Für einen aussagekräftigen Verlauf braucht es mehrere abgeschlossene Listen.`:'Noch keine Anwesenheitsdaten. Nach den ersten gespeicherten Kontrollen erscheint hier die Entwicklung.'}</div><div class="chart-foot"><span><i class="legend-blue"></i> Berechnet aus kontrollierten Einträgen</span><b>Nicht kontrollierte Einträge ausgeschlossen</b></div></section><section class="panel quick-panel"><div class="panel-head"><div><h2>Schnellzugriff</h2><p>Häufig verwendete Funktionen</p></div></div><button class="quick-link" data-page="attendance"><span class="quick-icon green">✓</span><span><b>Anwesenheit erfassen</b><small>Liste öffnen oder fortsetzen</small></span><span>→</span></button><button class="quick-link" data-page="classes"><span class="quick-icon blue">▦</span><span><b>Klassen verwalten</b><small>${cl} Klassen im Überblick</small></span><span>→</span></button><button class="quick-link" data-page="timetable"><span class="quick-icon violet">▤</span><span><b>Stundenplan ansehen</b><small>Wochenübersicht öffnen</small></span><span>→</span></button><button class="quick-link" data-page="reports"><span class="quick-icon amber">▧</span><span><b>Bericht erstellen</b><small>Übersicht exportieren</small></span><span>→</span></button></section><section class="panel activity-panel"><div class="panel-head"><div><h2>Letzte Anwesenheitslisten</h2><p>Aktuelle gespeicherte Kontrollen</p></div><button class="text-button" data-page="attendance">Alle ansehen →</button></div><div id="dash-sessions" class="activity-list">${sessions.slice(0,5).map(x=>`<div class="activity-row"><span class="activity-icon green">✓</span><span><b>${esc(x.class_name)} · ${x.period}. Stunde</b><small>${esc(x.subject_name||'Unterricht')} · ${fmt(x.session_date)}</small></span><span class="pill ${x.status==='completed'?'success':'warning'}">${x.status==='completed'?'Abgeschlossen':'Offen'}</span></div>`).join('')||'<div class="empty">Noch keine Anwesenheitskontrollen vorhanden.</div>'}</div></section><section class="panel class-panel"><div class="panel-head"><div><h2>Klassenübersicht</h2><p>Aktive Schüler pro Klasse</p></div><button class="text-button" data-page="classes">Alle Klassen →</button></div><div class="class-mini-list">${data.classes.slice(0,5).map(c=>`<div><span class="class-dot">${esc(c.name)}</span><div class="mini-bar"><i style="width:${Math.min(100,c.student_count*3)}%"></i></div><b>${c.student_count}</b></div>`).join('')}</div></section></div>`}
function classesPage(v){const manage=['admin','leadership'].includes(user.role);const render=()=>{v.innerHTML=title('Klassenverwaltung','Alle Klassen auf einen Blick',manage?'<button class="primary" id="add-class">＋ Klasse erstellen</button>':'')+`<div class="toolbar"><div class="filter-search"><span>⌕</span><input id="class-search" placeholder="Klasse suchen …"></div><span class="muted">${data.classes.length} Klassen</span><div class="spacer"></div><button class="view-toggle active" data-view="grid">▦</button><button class="view-toggle" data-view="list">☷</button></div><div class="class-grid">${data.classes.map((c,i)=>`<article class="class-card accent-${i%5}"><div class="class-card-head"><span class="class-name">${esc(c.name)}</span>${manage?`<div><button class="more" aria-label="Klasse bearbeiten" data-edit-class="${c.id}">✎</button><button class="more" aria-label="Klasse archivieren" data-archive-class="${c.id}">···</button></div>`:''}</div><div class="student-count">${c.student_count} <small>Schülerinnen & Schüler</small></div><div class="class-meta"><span class="avatar small">${initials(c.teacher_name||'')}</span><span><small>Klassenleitung</small><b>${esc(c.teacher_name||'Nicht zugewiesen')}</b></span><span class="room">⌖ ${esc(c.room||'Kein Raum')}</span></div><button class="card-link" data-class="${c.id}">Klasse ansehen <span>→</span></button></article>`).join('')}</div>`;$('#class-search').oninput=e=>document.querySelectorAll('.class-card').forEach(c=>c.hidden=!c.innerText.toLowerCase().includes(e.target.value.toLowerCase()));$('#add-class')?.addEventListener('click',()=>classDialog());document.querySelectorAll('[data-edit-class]').forEach(b=>b.onclick=()=>classDialog(data.classes.find(x=>x.id===b.dataset.editClass)));document.querySelectorAll('[data-archive-class]').forEach(b=>b.onclick=async()=>{const c=data.classes.find(x=>x.id===b.dataset.archiveClass);if(!confirm(`Klasse ${c.name} archivieren? Die historischen Anwesenheitsdaten bleiben erhalten.`))return;try{await api(`/classes/${c.id}`,{method:'DELETE'});await refreshData();classesPage(v);notify('Klasse archiviert.')}catch(e){notify(e.message)}});document.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{selectedClassId=b.dataset.class;go('classDetail')});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));$('.class-grid').classList.toggle('list-view',b.dataset.view==='list')})};function classDialog(c){const editing=!!c;dialog(editing?'Klasse bearbeiten':'Neue Klasse',`<form id="class-form"><label>Klassenname<input name="name" required maxlength="40" value="${esc(c?.name||'')}"></label><label>Klassenleitung<select name="teacherId"><option value="">Nicht zugewiesen</option>${(data.teachers||[]).map(t=>`<option value="${t.id}" ${c?.teacher_id===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>Raum<input name="room" maxlength="40" value="${esc(c?.room||'')}"></label><button class="primary full">${editing?'Änderungen speichern':'Klasse anlegen'}</button></form>`);$('#class-form').onsubmit=async e=>{e.preventDefault();try{await api(editing?`/classes/${c.id}`:'/classes',{method:editing?'PUT':'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeDialog();await refreshData();classesPage(v);notify(editing?'Klasse gespeichert.':'Klasse angelegt.')}catch(err){notify(err.message)}}}render()}
function classDetailPage(v){const c=data.classes.find(x=>x.id===selectedClassId);if(!c){go('classes');return}const students=data.students.filter(s=>s.class_id===c.id);const sessions=(data.sessions||[]).filter(s=>s.class_id===c.id);const manage=['admin','leadership'].includes(user.role);const stats=attendanceByClass(sessions,[c])[0];v.innerHTML=title(`Klasse ${esc(c.name)}`,`${c.student_count} Schülerinnen und Schüler · Klassenleitung ${esc(c.teacher_name||'nicht zugewiesen')}`,`<button class="secondary" id="class-detail-back">← Klassen</button><button class="primary" id="class-attendance">＋ Anwesenheit</button>`)+`<div class="stat-grid"><article class="stat-card blue"><div class="stat-label">Schüler/innen <span>♙</span></div><strong>${students.length}</strong><small>Aktive Klassenmitglieder</small></article><article class="stat-card violet"><div class="stat-label">Anwesenheitsquote <span>◉</span></div><strong>${stats.attendanceRate===null?'—':`${stats.attendanceRate}%`}</strong><small>Aus kontrollierten Einträgen</small></article><article class="stat-card amber"><div class="stat-label">Kontrollen <span>✓</span></div><strong>${sessions.length||'—'}</strong><small>Gespeicherte Sitzungen</small></article><article class="stat-card cyan"><div class="stat-label">Raum <span>⌖</span></div><strong>${esc(c.room||'—')}</strong><small>Klassenraum</small></article></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Schülerliste</h2><p>Aktuelle Klassenmitglieder</p></div>${manage?'<button class="text-button" id="class-add-student">Schüler hinzufügen</button>':''}</div><div class="detail-students">${students.map(s=>`<button class="quick-link" data-detail-student="${s.id}"><span class="avatar student-avatar">${initials(s.first_name+' '+s.last_name)}</span><span><b>${esc(s.last_name)}, ${esc(s.first_name)}</b><small>${esc(s.student_code)}</small></span><span>→</span></button>`).join('')||'<p class="empty">Keine aktiven Schüler in dieser Klasse.</p>'}</div></section><section class="panel"><div class="panel-head"><div><h2>Anwesenheitskontrollen</h2><p>Liste nach Datum und Unterrichtsstunde</p></div></div><div class="activity-list">${sessions.map(s=>`<button class="quick-link" data-detail-session="${s.id}"><span class="quick-icon ${s.status==='completed'?'green':'amber'}">${s.status==='completed'?'✓':'◷'}</span><span><b>${fmt(s.session_date)} · ${s.period}. Stunde</b><small>${esc(s.subject_name||'Unterricht')} · ${s.recorded}/${s.total} erfasst</small></span><span class="pill ${s.status==='completed'?'success':'warning'}">${s.status==='completed'?'Abgeschlossen':'Offen'}</span></button>`).join('')||'<p class="empty">Noch keine Anwesenheitskontrollen.</p>'}</div></section></div>`;$('#class-detail-back').onclick=()=>go('classes');$('#class-attendance').onclick=()=>{attendanceDefaultClassId=c.id;go('attendance');setTimeout(()=>$('#new-attendance')?.click(),0)};document.querySelectorAll('[data-detail-student]').forEach(b=>b.onclick=()=>{selectedStudentId=b.dataset.detailStudent;go('studentDetail')});document.querySelectorAll('[data-detail-session]').forEach(b=>b.onclick=()=>{currentAttendance=b.dataset.detailSession;go('attendance')});$('#class-add-student')?.addEventListener('click',()=>{go('students');setTimeout(()=>$('#add-student')?.click(),0)})}
async function studentDetailPage(v){try{const s=await api(`/students/${selectedStudentId}`);const records=s.attendance||[];const counts=records.reduce((a,r)=>(a[r.status]=(a[r.status]||0)+1,a),{});const manager=['admin','leadership'].includes(user.role);let history=[];if(manager)history=await api(`/students/${s.id}/history`);v.innerHTML=title(`${esc(s.first_name)} ${esc(s.last_name)}`,`Schülerkennung ${esc(s.student_code)} · Klasse ${esc(s.class_name||'—')}`,`<button class="secondary" id="student-detail-back">← Schülerliste</button>`)+`<div class="stat-grid"><article class="stat-card blue"><div class="stat-label">Anwesenheitskontrollen <span>✓</span></div><strong>${records.length||'—'}</strong><small>Gespeicherte Einträge</small></article><article class="stat-card green"><div class="stat-label">Anwesend <span>✓</span></div><strong>${counts.present||'—'}</strong><small>Kontrollierte Stunden</small></article><article class="stat-card red"><div class="stat-label">Abwesend <span>×</span></div><strong>${(counts.excused||0)+(counts.unexcused||0)||'—'}</strong><small>Entschuldigt oder unentschuldigt</small></article><article class="stat-card amber"><div class="stat-label">Verspätet <span>◷</span></div><strong>${counts.late||'—'}</strong><small>Gespeicherte Einträge</small></article></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Anwesenheitsverlauf</h2><p>Die neuesten gespeicherten Unterrichtsstunden</p></div></div><div class="table-scroll"><table><thead><tr><th>Datum</th><th>Stunde</th><th>Fach</th><th>Status</th></tr></thead><tbody>${records.map(r=>`<tr><td>${fmt(r.session_date)}</td><td>${r.period}. Stunde</td><td>${esc(r.subject_name||'—')}</td><td>${esc(stateLabel[r.status]||r.status)}</td></tr>`).join('')||'<tr><td class="empty" colspan="4">Noch keine Anwesenheitsdaten.</td></tr>'}</tbody></table></div></section>${manager?`<section class="panel"><div class="panel-head"><div><h2>Klassenhistorie</h2><p>Wechsel bleiben nachvollziehbar</p></div></div><div class="history-list">${history.map(h=>`<div><b>${esc(h.classes?.name||'Klasse')}</b><span>${fmt(h.starts_on)} – ${h.ends_on?fmt(h.ends_on):'heute'}</span></div>`).join('')||'<p class="muted">Keine Klassenwechsel erfasst.</p>'}</div></section>`:''}</div>`;$('#student-detail-back').onclick=()=>go('students')}catch(e){notify(e.message);go('students')}}
function studentsPage(v){const manage=['admin','leadership'].includes(user.role);const drawRows=()=>{const q=($('#student-filter')?.value||searchText).toLowerCase(),cl=$('#class-filter')?.value||'';const rows=data.students.filter(s=>`${s.first_name} ${s.last_name} ${s.class_name}`.toLowerCase().includes(q)&&(!cl||s.class_name===cl));$('.result-count').textContent=`${rows.length} Einträge`;document.querySelector('tbody').innerHTML=rows.map(s=>`<tr><td><div class="person"><span class="avatar student-avatar">${initials(s.first_name+' '+s.last_name)}</span><button class="person-link" data-student-detail="${s.id}">${esc(s.last_name)}, ${esc(s.first_name)}</button></div></td><td class="muted">${esc(s.student_code)}</td><td><span class="class-tag">${esc(s.class_name||'—')}</span></td><td><span class="pill success">Aktiv</span></td><td>${manage?`<button class="row-more" data-student-history="${s.id}" title="Klassenhistorie">◷</button><button class="row-more" data-edit-student="${s.id}" title="Bearbeiten">✎</button><button class="row-more" data-disable-student="${s.id}" title="Deaktivieren">×</button>`:''}</td></tr>`).join('')||'<tr><td class="empty" colspan="5">Keine passenden Schüler gefunden.</td></tr>';document.querySelectorAll('[data-student-detail]').forEach(b=>b.onclick=()=>{selectedStudentId=b.dataset.studentDetail;go('studentDetail')});document.querySelectorAll('[data-edit-student]').forEach(b=>b.onclick=()=>studentDialog(data.students.find(x=>x.id===b.dataset.editStudent)));document.querySelectorAll('[data-disable-student]').forEach(b=>b.onclick=async()=>{const s=data.students.find(x=>x.id===b.dataset.disableStudent);if(!confirm(`${s.first_name} ${s.last_name} deaktivieren?`))return;try{await api(`/students/${s.id}`,{method:'PUT',body:JSON.stringify({active:false})});await refreshData();studentsPage(v);notify('Schüler deaktiviert.')}catch(e){notify(e.message)}});document.querySelectorAll('[data-student-history]').forEach(b=>b.onclick=async()=>{try{const history=await api(`/students/${b.dataset.studentHistory}/history`);dialog('Klassenhistorie',`<div class="history-list">${history.map(h=>`<div><b>${esc(h.classes?.name||'Klasse')}</b><span>${fmt(h.starts_on)} – ${h.ends_on?fmt(h.ends_on):'heute'}</span></div>`).join('')||'<p class="muted">Noch keine Klassenwechsel protokolliert.</p>'}</div>`)}catch(e){notify(e.message)}})};v.innerHTML=title('Schülerverwaltung','Schülerinnen und Schüler verwalten',manage?'<button class="primary" id="add-student">＋ Schüler hinzufügen</button>':'')+`<div class="toolbar"><div class="filter-search"><span>⌕</span><input id="student-filter" placeholder="Name oder Klasse suchen …" value="${esc(searchText)}"></div><select id="class-filter"><option value="">Alle Klassen</option>${data.classes.map(c=>`<option>${esc(c.name)}</option>`).join('')}</select><span class="muted result-count"></span></div><section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Schüler/in</th><th>Schülerkennung</th><th>Klasse</th><th>Status</th><th></th></tr></thead><tbody></tbody></table></div></section>`;const filter=$('#student-filter');filter.oninput=()=>{searchText=filter.value;drawRows()};$('#class-filter').onchange=drawRows;drawRows();$('#add-student')?.addEventListener('click',()=>studentDialog());function studentDialog(s){const editing=!!s;dialog(editing?'Schüler bearbeiten':'Schüler hinzufügen',`<form id="student-form"><div class="form-row"><label>Vorname<input name="firstName" required maxlength="80" value="${esc(s?.first_name||'')}"></label><label>Nachname<input name="lastName" required maxlength="80" value="${esc(s?.last_name||'')}"></label></div><label>Klasse<select name="classId" required>${data.classes.map(c=>`<option value="${c.id}" ${s?.class_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><p class="form-hint">Es werden nur Name, interne Kennung und Klasse gespeichert. Klassenwechsel werden historisch gespeichert.</p><button class="primary full">${editing?'Änderungen speichern':'Schüler hinzufügen'}</button></form>`);$('#student-form').onsubmit=async e=>{e.preventDefault();try{await api(editing?`/students/${s.id}`:'/students',{method:editing?'PUT':'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeDialog();await refreshData();studentsPage(v);notify(editing?'Schülerdaten gespeichert.':'Schüler angelegt.')}catch(err){notify(err.message)}}}}
const stateLabel={present:'Anwesend',excused:'Entschuldigt',unexcused:'Unentschuldigt',late:'Verspätet',unchecked:'Nicht kontrolliert'};
function attendancePage(v){api('/attendance').then(s=>{data.sessions=s;renderAttendanceList()});renderAttendanceList();function renderAttendanceList(){if(currentAttendance)return attendanceEditor(v);const sessions=data.sessions||[];v.innerHTML=title('Anwesenheit','Digitale Anwesenheitskontrolle',`<button class="primary" id="new-attendance">＋ Neue Kontrolle</button>`)+`<div class="toolbar"><div class="filter-search"><span>⌕</span><input id="att-search" placeholder="Klasse oder Fach suchen …"></div><select id="att-status"><option value="">Alle Status</option><option value="open">Offen</option><option value="completed">Abgeschlossen</option></select><span class="muted">${sessions.length} Kontrollen</span></div><section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Klasse</th><th>Datum</th><th>Stunde</th><th>Fach</th><th>Erfasst</th><th>Status</th><th></th></tr></thead><tbody>${sessions.map(s=>`<tr><td><span class="class-tag">${esc(s.class_name)}</span></td><td>${fmt(s.session_date)}</td><td>${s.period}. Stunde</td><td>${esc(s.subject_name||'—')}</td><td>${s.recorded}/${s.total}</td><td><span class="pill ${s.status==='completed'?'success':'warning'}">${s.status==='completed'?'Abgeschlossen':'Offen'}</span></td><td><button class="small-secondary" data-open="${s.id}">Öffnen →</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Noch keine Anwesenheitskontrollen vorhanden.</td></tr>'}</tbody></table></div></section>`;document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{currentAttendance=b.dataset.open;renderAttendanceList()});$('#new-attendance').onclick=()=>dialog('Neue Anwesenheitskontrolle',`<form id="new-att-form"><label>Klasse<select name="classId" required>${data.classes.map(c=>`<option value="${c.id}" ${attendanceDefaultClassId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div class="form-row"><label>Datum<input name="date" type="date" value="${dateToday()}" required></label><label>Stunde<select name="period">${Array.from({length:12},(_,i)=>`<option value="${i+1}">${i+1}. Stunde</option>`).join('')}</select></label></div><label>Fach<select name="subjectId">${data.subjects.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><button class="primary full">Kontrolle öffnen</button></form>`);$('#new-att-form')?.addEventListener('submit',async e=>{e.preventDefault();try{const s=await api('/attendance',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeDialog();attendanceDefaultClassId=null;currentAttendance=s.id;renderAttendanceList()}catch(err){notify(err.message)}});$('#att-search').oninput=e=>document.querySelectorAll('tbody tr').forEach(r=>r.hidden=!r.innerText.toLowerCase().includes(e.target.value.toLowerCase()));$('#att-status').onchange=e=>document.querySelectorAll('tbody tr').forEach(r=>r.hidden=!!e.target.value&&!r.innerText.toLowerCase().includes(e.target.value==='open'?'offen':'abgeschlossen'))}}
async function attendanceEditor(v){const d=await api('/attendance/'+currentAttendance);const statuses={present:0,excused:0,unexcused:0,late:0,unchecked:0};d.records.forEach(r=>statuses[r.status]++);v.innerHTML=title(`Anwesenheit · ${esc(d.session.class_name)}`,`${fmt(d.session.session_date)} · ${d.session.period}. Stunde · ${esc(d.session.subject_name||'Unterricht')}`,`<button class="secondary" id="back-att">← Zurück</button>`)+`<div class="attendance-meta"><span class="pill ${d.session.status==='completed'?'success':'warning'}">${d.session.status==='completed'?'Abgeschlossen':'Entwurf · nicht gespeichert'}</span><span>${d.records.length} Schülerinnen und Schüler</span><span>Lehrkraft: ${esc(user.name)}</span></div><div class="status-summary">${Object.entries(statuses).map(([k,n])=>`<div class="status-count ${k}"><span>${stateLabel[k]}</span><b>${n}</b></div>`).join('')}</div><section class="panel attendance-panel"><div class="attendance-toolbar"><div><h2>Klassenliste</h2><p>${d.session.status==='completed'?'Abgeschlossene Liste · Korrekturen werden protokolliert.':'Status auswählen oder alle als anwesend markieren.'}</p></div>${d.session.status==='completed'&&['admin','leadership'].includes(user.role)?'<label class="reason-field">Änderungsgrund<input id="change-reason" maxlength="300" placeholder="Grund für die Korrektur"></label>':''}${d.session.status!=='completed'?'<button id="all-present" class="small-secondary">✓ Alle anwesend</button>':''}</div><div class="attendance-rows">${d.records.map((r,i)=>`<div class="attendance-row" data-student="${r.student_id}"><span class="number">${String(i+1).padStart(2,'0')}</span><span class="student-name"><span class="avatar student-avatar">${initials(r.first_name+' '+r.last_name)}</span><b>${esc(r.last_name)}, ${esc(r.first_name)}</b></span><span class="student-code">${esc(r.student_code)}</span><div class="status-select" role="group" aria-label="Status ${esc(r.first_name)} ${esc(r.last_name)}">${Object.entries(stateLabel).map(([k,l])=>`<button class="status-option ${r.status===k?'selected '+k:''}" data-status="${k}" title="${l}">${stateIcon(k)} <span>${l}</span></button>`).join('')}</div></div>`).join('')}</div><div class="attendance-footer"><span id="save-state">Änderungen noch nicht gespeichert</span><div><button class="secondary" id="save-att">Speichern</button><button class="primary" id="complete-att">Liste abschließen</button></div></div></section>`;$('#back-att').onclick=()=>{currentAttendance=null;attendancePage(v)};const updateCount=()=>{Object.keys(statuses).forEach(k=>statuses[k]=0);document.querySelectorAll('.attendance-row').forEach(row=>{const s=row.querySelector('.selected').dataset.status;statuses[s]++});document.querySelectorAll('.status-count').forEach(el=>el.querySelector('b').textContent=statuses[Object.keys(statusLabel).find(k=>stateLabel[k]===el.querySelector('span').textContent)]);$('#save-state').textContent='Ungespeicherte Änderungen'};document.querySelectorAll('.status-option').forEach(b=>b.onclick=()=>{const row=b.closest('.attendance-row');row.querySelectorAll('.status-option').forEach(x=>x.className='status-option');b.className='status-option selected '+b.dataset.status;updateCount()});$('#all-present')?.addEventListener('click',()=>{document.querySelectorAll('.attendance-row').forEach(row=>{row.querySelectorAll('.status-option').forEach(x=>x.className='status-option');row.querySelector('[data-status="present"]').className='status-option selected present'});updateCount()});const save=async complete=>{const records=[...document.querySelectorAll('.attendance-row')].map(row=>({studentId:row.dataset.student,status:row.querySelector('.selected').dataset.status}));try{await api('/attendance/'+currentAttendance,{method:'PUT',body:JSON.stringify({records,complete,reason:$('#change-reason')?.value||''})});$('#save-state').textContent='Gespeichert';notify(complete?'Anwesenheitsliste abgeschlossen.':'Anwesenheit gespeichert.');if(complete){currentAttendance=null;attendancePage(v)}}catch(err){notify(err.message)}};$('#save-att').textContent=d.session.status==='completed'?'Korrektur speichern':'Speichern';$('#save-att').onclick=()=>save(false);$('#complete-att').hidden=d.session.status==='completed';$('#complete-att').onclick=()=>save(true)}
function stateIcon(k){return {present:'✓',excused:'⊘',unexcused:'×',late:'◷',unchecked:'·'}[k]}
function absencesPage(v){v.innerHTML=title('Fehlzeiten','Entschuldigte, unentschuldigte Fehlzeiten und Verspätungen',`<button class="secondary" id="absence-csv">CSV exportieren</button>`)+`<div class="toolbar"><div class="filter-search"><span>⌕</span><input id="absence-search" placeholder="Schüler oder Klasse suchen …"></div><select id="absence-type"><option value="">Alle Status</option><option value="excused">Entschuldigt</option><option value="unexcused">Unentschuldigt</option><option value="late">Verspätet</option></select><select id="absence-period"><option value="month">Dieser Monat</option><option value="day">Heute</option><option value="week">Diese Woche</option><option value="school">Schuljahr</option><option value="custom">Zeitraum wählen</option></select><label class="date-filter">Von<input id="absence-from" type="date"></label><label class="date-filter">Bis<input id="absence-to" type="date"></label><button class="secondary" id="absence-load">Anwenden</button></div><div class="stat-grid small-stats"><article class="stat-card amber"><div class="stat-label">Entschuldigt <span>⊘</span></div><strong id="absence-excused">—</strong><small>Gespeicherte Einträge</small></article><article class="stat-card red"><div class="stat-label">Unentschuldigt <span>×</span></div><strong id="absence-unexcused">—</strong><small>Gespeicherte Einträge</small></article><article class="stat-card orange"><div class="stat-label">Verspätungen <span>◷</span></div><strong id="absence-late">—</strong><small>Gespeicherte Einträge</small></article><article class="stat-card blue"><div class="stat-label">Offene Listen <span>·</span></div><strong>${(data.sessions||[]).filter(x=>x.status==='open').length||'—'}</strong><small>Nicht abgeschlossen</small></article></div><section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Schüler/in</th><th>Klasse</th><th>Datum</th><th>Stunde / Fach</th><th>Status</th><th></th></tr></thead><tbody><tr><td colspan="6" class="empty">Fehlzeiten werden geladen …</td></tr></tbody></table></div></section>`;let all=[];const d=x=>`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`;function range(){const now=new Date(),today=dateToday();let from=$('#absence-from').value,to=$('#absence-to').value;switch($('#absence-period').value){case'day':from=to=today;break;case'week':{const a=new Date(now);a.setDate(a.getDate()-((a.getDay()+6)%7));from=d(a);to=today;break}case'month':from=`${today.slice(0,7)}-01`;to=today;break;case'school':from=`${data.school.school_year.slice(0,4)}-08-01`;to=today;break}$('#absence-from').value=from;$('#absence-to').value=to;return {from,to}}async function load(){try{const {from,to}=range();all=await api(`/absences?from=${from}&to=${to}`);for(const s of ['excused','unexcused','late'])$(`#absence-${s}`).textContent=all.filter(r=>r.status===s).length||'—';paint()}catch(e){notify(e.message)}}function paint(){const q=$('#absence-search').value.toLowerCase(),status=$('#absence-type').value;const rows=all.filter(r=>(!status||r.status===status)&&`${r.first_name} ${r.last_name} ${r.class_name}`.toLowerCase().includes(q));document.querySelector('tbody').innerHTML=rows.map(r=>`<tr><td><div class="person"><span class="avatar student-avatar">${initials(r.first_name+' '+r.last_name)}</span><b>${esc(r.last_name)}, ${esc(r.first_name)}</b></div></td><td>${esc(r.class_name||'—')}</td><td>${fmt(r.session_date)}</td><td>${r.period}. Stunde · ${esc(r.subject_name||'—')}</td><td><span class="pill ${r.status==='excused'?'info':r.status==='late'?'warning':'danger'}">${stateLabel[r.status]}</span>${r.detail?.reviewed_at?'<small class="muted"> geprüft</small>':''}</td><td><button class="small-secondary" data-absence-session="${r.session_id}">Liste öffnen</button>${['admin','leadership'].includes(user.role)?` <button class="row-more" data-review-absence="${r.id}" title="Entschuldigung prüfen">✎</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Keine passenden Fehlzeiten im gewählten Zeitraum.</td></tr>';document.querySelectorAll('[data-absence-session]').forEach(b=>b.onclick=()=>{currentAttendance=b.dataset.absenceSession;go('attendance')});document.querySelectorAll('[data-review-absence]').forEach(b=>b.onclick=()=>{const r=all.find(x=>x.id===b.dataset.reviewAbsence);dialog('Entschuldigung prüfen',`<form id="review-absence"><p>${esc(r.first_name)} ${esc(r.last_name)} · ${fmt(r.session_date)} · ${stateLabel[r.status]}</p><label>Interne Notiz<input name="note" maxlength="1000" value="${esc(r.detail?.note||'')}"></label><p class="form-hint">Die Notiz ist nur für berechtigte Mitarbeitende sichtbar.</p><button class="primary full">Prüfung speichern</button></form>`);$('#review-absence').onsubmit=async e=>{e.preventDefault();try{await api(`/absences/${r.id}`,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeDialog();await load();notify('Prüfung gespeichert.')}catch(e){notify(e.message)}}})}$('#absence-search').oninput=paint;$('#absence-type').onchange=paint;$('#absence-period').onchange=()=>{const custom=$('#absence-period').value==='custom';$('#absence-from').disabled=$('#absence-to').disabled=!custom;if(!custom)load()};$('#absence-from').disabled=$('#absence-to').disabled=true;$('#absence-load').onclick=load;$('#absence-csv').onclick=async()=>{try{await api('/audit/export',{method:'POST',body:JSON.stringify({type:'Fehlzeiten'})});exportCSV('Fehlzeiten.csv',['Schüler/in','Klasse','Datum','Stunde','Fach','Status'],all.map(r=>[r.first_name+' '+r.last_name,r.class_name,r.session_date,r.period,r.subject_name,stateLabel[r.status]]))}catch(e){notify(e.message)}};load()}
function timetablePage(v){const manage=['admin','leadership'].includes(user.role);const weekdays=['Montag','Dienstag','Mittwoch','Donnerstag','Freitag'];const periods=Array.from({length:12},(_,i)=>i+1);let slots=[];v.innerHTML=title('Stundenplan','Wochenübersicht für Klassen und Lehrkräfte',manage?'<button class="primary" id="add-lesson">＋ Stunde hinzufügen</button>':'')+`<div class="toolbar"><select id="timetable-class"><option value="">Alle freigegebenen Klassen</option>${data.classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><span class="muted">Wiederkehrender Wochenplan</span></div><section class="panel timetable-panel"><div class="timetable-grid"><div class="time-head">Stunde</div>${weekdays.map(d=>`<div class="day-head">${d}</div>`).join('')}${periods.map(p=>`<div class="time-cell">${p}. Stunde</div>${weekdays.map((_,day)=>`<div class="lesson-cell" data-day="${day+1}" data-period="${p}"></div>`).join('')}`).join('')}</div></section>`;async function load(){try{const q=$('#timetable-class').value;slots=await api(`/timetable${q?'?classId='+encodeURIComponent(q):user.role==='teacher'?'?teacherId='+encodeURIComponent(user.id):''}`);document.querySelectorAll('.lesson-cell').forEach(cell=>{const matches=slots.filter(x=>x.weekday===Number(cell.dataset.day)&&x.period===Number(cell.dataset.period));cell.innerHTML=matches.map(x=>`<div class="lesson ${['blue','violet','green','amber','cyan'][x.period%5]}"><b>${esc(x.subject_name)}</b><small>${esc(x.class_name)} · ${esc(x.teacher_name||'')}</small><small>${esc(x.room_name||'Kein Raum')}</small>${manage?`<button class="lesson-edit" data-edit-slot="${x.id}">Bearbeiten</button>`:''}</div>`).join('')||'<span class="lesson-none">—</span>'});document.querySelectorAll('[data-edit-slot]').forEach(b=>b.onclick=()=>lessonDialog(slots.find(x=>x.id===b.dataset.editSlot)))}catch(e){notify(e.message)}}function lessonDialog(slot){dialog(slot?'Stunde bearbeiten':'Stunde hinzufügen',`<form id="lesson-form"><label>Klasse<select name="classId" required>${data.classes.map(c=>`<option value="${c.id}" ${slot?.class_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div class="form-row"><label>Wochentag<select name="weekday">${weekdays.map((d,i)=>`<option value="${i+1}" ${slot?.weekday===i+1?'selected':''}>${d}</option>`).join('')}</select></label><label>Stunde<select name="period">${periods.map(p=>`<option value="${p}" ${slot?.period===p?'selected':''}>${p}. Stunde</option>`).join('')}</select></label></div><label>Fach<select name="subjectId">${data.subjects.map(s=>`<option value="${s.id}" ${slot?.subject_id===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Lehrkraft<select name="teacherId"><option value="">Nicht zugewiesen</option>${(data.teachers||[]).map(t=>`<option value="${t.id}" ${slot?.teacher_id===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>Raum<select name="roomId"><option value="">Kein Raum</option>${(data.rooms||[]).map(r=>`<option value="${r.id}" ${slot?.room_id===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><div class="form-row"><label>Beginn<input name="startsAt" type="time" value="${slot?.starts_at?.slice(0,5)||''}"></label><label>Ende<input name="endsAt" type="time" value="${slot?.ends_at?.slice(0,5)||''}"></label></div><button class="primary full">${slot?'Änderungen speichern':'Stunde speichern'}</button></form>`);$('#lesson-form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));if(slot)b.id=slot.id;try{await api('/timetable',{method:'POST',body:JSON.stringify(b)});closeDialog();await load();notify('Stundenplan gespeichert.')}catch(e){notify(e.message)}}}$('#timetable-class').onchange=load;$('#add-lesson')?.addEventListener('click',()=>lessonDialog());load()}
function substitutionsPage(v){const manage=['admin','leadership'].includes(user.role);let substitutions=[];v.innerHTML=title('Vertretungsplan','Tagesübersicht und Vertretungen',manage?'<button class="primary" id="add-sub">＋ Vertretung eintragen</button>':'')+`<div class="toolbar"><label class="date-filter">Ab<input id="sub-from" type="date" value="${dateToday()}"></label><label class="date-filter">Bis<input id="sub-to" type="date" value="${dateToday()}"></label><button class="secondary" id="sub-search">Anzeigen</button></div><section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Datum</th><th>Klasse / Stunde</th><th>Fach</th><th>Vertretung</th><th>Raum</th><th></th></tr></thead><tbody><tr><td class="empty" colspan="6">Vertretungen werden geladen …</td></tr></tbody></table></div></section>`;async function load(){try{substitutions=await api(`/substitutions?from=${$('#sub-from').value}&to=${$('#sub-to').value}`);document.querySelector('tbody').innerHTML=substitutions.map(s=>`<tr><td>${fmt(s.substitution_date)}</td><td><span class="class-tag">${esc(s.class_name)}</span> · ${s.period}. Stunde</td><td>${esc(s.subject_name||'—')}</td><td>${esc(s.substitute_name||'—')}</td><td>${esc(s.room_name||'—')}</td><td>${s.substitution_date===dateToday()&&user.role==='teacher'?`<button class="small-secondary" data-sub-attendance="${s.id}">Anwesenheit öffnen</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Keine Vertretungen für diesen Zeitraum eingetragen.</td></tr>';document.querySelectorAll('[data-sub-attendance]').forEach(b=>b.onclick=async()=>{try{const session=await api(`/substitutions/${b.dataset.subAttendance}/attendance`,{method:'POST'});currentAttendance=session.id;go('attendance')}catch(e){notify(e.message)}})}catch(e){notify(e.message)}}$('#sub-search').onclick=load;if(manage)$('#add-sub').onclick=async()=>{try{const [teachers,rooms]=await Promise.all([api('/teachers'),api('/rooms')]);data.teachers=teachers;data.rooms=rooms;dialog('Vertretung eintragen',`<form id="sub-form"><label>Klasse<select name="classId" required>${data.classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><div class="form-row"><label>Datum<input name="date" type="date" value="${dateToday()}" required></label><label>Stunde<select name="period">${Array.from({length:10},(_,i)=>`<option value="${i+1}">${i+1}. Stunde</option>`).join('')}</select></label></div><label>Fach<select name="subjectId"><option value="">Wie Stundenplan</option>${data.subjects.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><label>Vertretungslehrkraft<select name="substituteTeacherId" required>${teachers.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label><label>Raum<select name="roomId"><option value="">Wie Stundenplan</option>${rooms.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select></label><label>Hinweis<input name="note" maxlength="300" placeholder="Optionaler organisatorischer Hinweis"></label><button class="primary full">Vertretung speichern</button></form>`);$('#sub-form').onsubmit=async e=>{e.preventDefault();try{await api('/substitutions',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeDialog();await load();notify('Vertretung gespeichert und Beteiligte benachrichtigt.')}catch(e){notify(e.message)}}}catch(e){notify(e.message)}};load()}
function statisticsPage(v){const dateString=x=>`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`;v.innerHTML=title('Statistiken & Auswertungen','Datenbasiert, transparent und rollenabhängig','')+`<div class="toolbar"><select id="statistics-period"><option value="school">Schuljahr</option><option value="today">Heute</option><option value="week">Diese Woche</option><option value="month">Dieser Monat</option><option value="custom">Zeitraum wählen</option></select><label class="date-filter">Von<input id="statistics-from" type="date" disabled></label><label class="date-filter">Bis<input id="statistics-to" type="date" disabled></label><button class="secondary" id="statistics-apply" hidden>Anwenden</button></div><div id="statistics-result"></div>`;const renderStats=sessions=>{const summary=summarizeAttendance(sessions);const rate=summary.attendanceRate===null?'—':`${summary.attendanceRate}%`;const byClass=attendanceByClass(sessions,data.classes);$('#statistics-result').innerHTML=`<div class="stat-grid"><article class="stat-card green"><div class="stat-label">Erfasste Einträge <span>✓</span></div><strong>${summary.recorded||'—'}</strong><small>Im gewählten Zeitraum</small></article><article class="stat-card blue"><div class="stat-label">Anwesenheitsquote <span>◉</span></div><strong>${rate}</strong><small>Kontrollierte Statuswerte</small></article><article class="stat-card amber"><div class="stat-label">Offene Kontrollen <span>◷</span></div><strong>${summary.openSessions||'—'}</strong><small>Listen nicht abgeschlossen</small></article><article class="stat-card violet"><div class="stat-label">Klassen erfasst <span>▦</span></div><strong>${summary.classCount||'—'}</strong><small>Mit Anwesenheitsdaten</small></article></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Anwesenheit nach Klasse</h2><p>Nur gültige, kontrollierte Einträge</p></div></div><div class="class-mini-list">${byClass.map(x=>`<div><span class="class-dot">${esc(x.className)}</span><div class="mini-bar"><i style="width:${x.attendanceRate??0}%"></i></div><b>${x.attendanceRate===null?'—':`${x.attendanceRate}%`}</b></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>Berechnungslogik</h2><p>Transparenz der Kennzahlen</p></div></div><div class="logic-note"><b>Anwesenheitsquote</b><p>Anwesend plus verspätet ÷ alle kontrollierten Einträge. Entschuldigte und unentschuldigte Abwesenheiten zählen als abwesend. Nicht kontrollierte Einträge bleiben ausgeschlossen.</p></div></section></div>`};function apply(){const value=$('#statistics-period').value,now=new Date(),today=dateToday();let from,to=today;if(value==='today')from=today;else if(value==='week'){const d=new Date(now);d.setDate(d.getDate()-((d.getDay()+6)%7));from=dateString(d)}else if(value==='month')from=`${today.slice(0,7)}-01`;else if(value==='custom'){from=$('#statistics-from').value;to=$('#statistics-to').value}else from=`${data.school.school_year.slice(0,4)}-08-01`;const filtered=(data.sessions||[]).filter(x=>x.session_date>=from&&x.session_date<=to);renderStats(filtered)}$('#statistics-period').onchange=()=>{const custom=$('#statistics-period').value==='custom';$('#statistics-from').disabled=$('#statistics-to').disabled=!custom;$('#statistics-apply').hidden=!custom;if(!custom)apply()};$('#statistics-apply').onclick=apply;apply()}
function reportsPage(v){v.innerHTML=title('Berichte','Druckansicht und CSV-Export für berechtigte Daten','')+`<div class="report-grid">${[['◷','Tagesanwesenheit','Kontrollen nach Datum und Klasse'],['▦','Klassenliste','Aktive Schüler pro Klasse'],['!','Fehlzeiten','Abwesenheit und Verspätungen'],['▥','Schulstatistik','Zusammenfassung gültiger Einträge']].map(([i,n,d])=>`<article class="panel report-card"><span class="report-icon">${i}</span><h2>${n}</h2><p>${d}</p><div><button class="small-secondary" data-report="${n}">CSV exportieren</button><button class="secondary print-report" data-print="${n}">Drucken / PDF</button></div></article>`).join('')}</div>`;document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>exportReport(b.dataset.report));document.querySelectorAll('[data-print]').forEach(b=>b.onclick=async()=>{try{await api('/audit/export',{method:'POST',body:JSON.stringify({type:b.dataset.print+' · PDF/Druck'})});window.print()}catch(e){notify(e.message)}})}
async function exportReport(name){try{await api('/audit/export',{method:'POST',body:JSON.stringify({type:name})});if(name==='Klassenliste')return exportCSV('Klassenliste.csv',['Klasse','Schülername','Interne Kennung'],data.students.map(s=>[s.class_name,`${s.first_name} ${s.last_name}`,s.student_code]));if(name==='Tagesanwesenheit'){const ss=await api('/attendance'),all=[];for(const x of ss){const d=await api('/attendance/'+x.id);d.records.forEach(r=>all.push([d.session.class_name,d.session.session_date,d.session.period,d.session.subject_name,r.first_name+' '+r.last_name,stateLabel[r.status]]))}return exportCSV('Tagesanwesenheit.csv',['Klasse','Datum','Stunde','Fach','Schüler','Status'],all)}if(name==='Schulstatistik'){const ss=await api('/attendance');return exportCSV('Schulstatistik.csv',['Klasse','Datum','Stunde','Status','Erfasst','Schüler'],ss.map(x=>[x.class_name,x.session_date,x.period,x.status,x.recorded,x.total]))}const abs=await api('/absences');return exportCSV('Fehlzeiten.csv',['Klasse','Datum','Stunde','Schüler','Status'],abs.map(x=>[x.class_name,x.session_date,x.period,x.first_name+' '+x.last_name,stateLabel[x.status]]))}catch(e){notify(e.message)}}
function exportCSV(filename,headers,rows){const csv=[headers,...rows].map(r=>r.map(c=>'"'+String(c??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download=filename;a.click();URL.revokeObjectURL(a.href);notify('CSV-Datei wurde exportiert.')}
async function notificationsPage(v){v.innerHTML=title('Benachrichtigungen','Aktuelle Hinweise und Aufgaben','<button class="text-button" id="mark-read">Alle als gelesen markieren</button>')+`<section class="panel empty-panel"><div class="empty-icon">♧</div><h2>Keine neuen Benachrichtigungen</h2><p>Neue Hinweise zu Anwesenheitslisten und Schuländerungen erscheinen hier.</p></section>`;$('#mark-read').onclick=()=>notify('Alle Benachrichtigungen sind gelesen.')}
function settingsPage(v){const admin=user.role==='admin',manage=['admin','leadership'].includes(user.role);v.innerHTML=title('Einstellungen','Schulprofil, persönliches Konto und Kalender',admin?'<button class="primary" id="save-school">Schulprofil speichern</button>':'')+`<div class="settings-stack">${admin?`<section class="panel settings-panel"><div class="panel-head"><div><h2>Schulprofil</h2><p>Angaben der Schule</p></div><div class="school-emblem compact">◆ <small>${esc(data.school.name.slice(0,2).toUpperCase())}</small></div></div><div class="settings-form"><label>Schulname<input id="school-name" value="${esc(data.school.name)}"></label><label>Adresse<input id="school-address" value="${esc(data.school.address)}"></label><div class="form-row"><label>Schuljahr<input id="school-year" value="${esc(data.school.school_year)}"></label><label>Zeitzone<input value="${esc(data.school.timezone)}" disabled></label></div></div></section>`:''}<section class="panel settings-panel"><div class="panel-head"><div><h2>Mein Profil</h2><p>Persönlicher Anzeigename und Passwort</p></div><span class="class-tag">${roleName(user.role)}</span></div><div class="settings-form"><label>Anzeigename<input id="profile-name" value="${esc(user.name)}" maxlength="100"></label><button class="secondary" id="save-profile">Profil speichern</button><hr><h2>Passwort ändern</h2><form id="password-form"><label>Neues Passwort<input name="password" type="password" minlength="12" required autocomplete="new-password"></label><label>Wiederholen<input name="confirm" type="password" minlength="12" required autocomplete="new-password"></label><button class="primary">Passwort ändern</button></form></div></section>${manage?`<section class="panel settings-panel"><div class="panel-head"><div><h2>Schuljahre</h2><p>Jahreswechsel mit erhaltener Historie</p></div></div><div class="settings-form"><form id="school-year-form"><label>Bezeichnung<input name="name" required maxlength="30" placeholder="2027/2028"></label><div class="form-row"><label>Beginn<input name="startsOn" type="date" required></label><label>Ende<input name="endsOn" type="date" required></label></div><button class="secondary">Als aktuelles Schuljahr setzen</button></form><div id="school-year-list" class="holiday-list"></div></div></section><section class="panel settings-panel"><div class="panel-head"><div><h2>Ferien und Feiertage</h2><p>Schulfreie Tage im Kalender</p></div></div><div class="settings-form"><form id="holiday-form"><label>Bezeichnung<input name="name" required maxlength="120"></label><div class="form-row"><label>Von<input name="startsOn" type="date" required></label><label>Bis<input name="endsOn" type="date" required></label></div><button class="secondary">Feiertag eintragen</button></form><div id="holiday-list" class="holiday-list"></div></div></section><section class="panel settings-panel"><div class="panel-head"><div><h2>Räume</h2><p>Ressourcen für den Stundenplan</p></div></div><div class="settings-form"><div class="form-row"><label>Neuer Raum<input id="room-name" maxlength="40"></label><label>Kapazität<input id="room-capacity" type="number" min="1"></label></div><button class="secondary" id="add-room">Raum hinzufügen</button><div id="room-list" class="holiday-list"></div></div></section>`:''}<div class="privacy-callout"><b>Datenschutz & Datenhaltung</b><p>Verwende ausschließlich fiktive Entwicklungsdaten, bis Hosting, Datenschutz, Aufbewahrung und Löschkonzept durch die Schule freigegeben sind.</p></div></div>`;$('#save-school')?.addEventListener('click',async()=>{try{await api('/settings/school',{method:'PUT',body:JSON.stringify({name:$('#school-name').value,address:$('#school-address').value,schoolYear:$('#school-year').value})});data=await api('/bootstrap');notify('Schulprofil gespeichert.')}catch(e){notify(e.message)}});$('#save-profile').onclick=async()=>{try{await api('/profile',{method:'PUT',body:JSON.stringify({name:$('#profile-name').value})});user.name=$('#profile-name').value;render();notify('Profil gespeichert.')}catch(e){notify(e.message)}};$('#password-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(f.get('password')!==f.get('confirm'))return notify('Die Passwörter stimmen nicht überein.');try{await api('/password',{method:'PUT',body:JSON.stringify({password:f.get('password')})});e.currentTarget.reset();notify('Passwort geändert.')}catch(e){notify(e.message)}};if(manage){const load=async()=>{try{const [holidays,rooms,years]=await Promise.all([api('/holidays'),api('/rooms'),api('/school-years')]);$('#school-year-list').innerHTML=years.map(y=>`<div><b>${esc(y.name)}</b> · ${fmt(y.starts_on)} – ${fmt(y.ends_on)}${y.active?' · aktuell':''}</div>`).join('')||'<p class="muted">Noch keine Schuljahre.</p>';$('#holiday-list').innerHTML=holidays.map(x=>`<div>${esc(x.name)} · ${fmt(x.starts_on)} – ${fmt(x.ends_on)}</div>`).join('')||'<p class="muted">Noch keine Ferien oder Feiertage eingetragen.</p>';$('#room-list').innerHTML=rooms.map(x=>`<div>${esc(x.name)}${x.capacity?` · ${x.capacity} Plätze`:''}</div>`).join('')||'<p class="muted">Noch keine Räume eingetragen.</p>'}catch(e){notify(e.message)}};$('#school-year-form').onsubmit=async e=>{e.preventDefault();try{await api('/school-years',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});e.currentTarget.reset();data=await api('/bootstrap');await load();notify('Schuljahr gespeichert.')}catch(e){notify(e.message)}};$('#holiday-form').onsubmit=async e=>{e.preventDefault();try{await api('/holidays',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});e.currentTarget.reset();await load();notify('Feiertag gespeichert.')}catch(e){notify(e.message)}};$('#add-room').onclick=async()=>{try{await api('/rooms',{method:'POST',body:JSON.stringify({name:$('#room-name').value,capacity:$('#room-capacity').value})});$('#room-name').value='';$('#room-capacity').value='';data.rooms=await api('/rooms');await load();notify('Raum angelegt.')}catch(e){notify(e.message)}};load()}}

async function adminPage(v){const users=await api('/admin/users');v.innerHTML=title('Administration','Benutzer und Zugriffsrollen verwalten','<button class="primary" id="add-user">＋ Benutzer anlegen</button>')+`<div class="admin-notice"><b>Geschützter Bereich</b><span>Änderungen werden im Audit-Log festgehalten. Deaktivierte Konten können sich nicht anmelden.</span></div><section class="panel table-panel"><div class="panel-head"><div><h2>Benutzerkonten</h2><p>${users.length} Benutzer im System</p></div></div><div class="table-scroll"><table><thead><tr><th>Name</th><th>E-Mail</th><th>Rolle</th><th>Status</th><th>Angelegt</th><th></th></tr></thead><tbody>${users.map(x=>`<tr><td><div class="person"><span class="avatar student-avatar">${initials(x.name)}</span><b>${esc(x.name)}</b></div></td><td>${esc(x.email)}</td><td>${roleName(x.role)}</td><td><span class="pill ${x.active?'success':'danger'}">${x.active?'Aktiv':'Deaktiviert'}</span></td><td>${fmt(x.created_at.slice(0,10))}</td><td><button class="small-secondary" data-edit-user="${x.id}" ${x.id===user.id?'disabled':''}>Rolle / Status ändern</button></td></tr>`).join('')}</tbody></table></div></section>`;function userDialog(x){dialog(x?'Benutzer ändern':'Benutzer anlegen',`<form id="create-user">${x?'':`<label>Name<input name="name" required maxlength="100"></label><label>E-Mail<input name="email" type="email" required></label><label>Temporäres Passwort<input name="password" type="password" minlength="12" required><small>Mindestens 12 Zeichen; sicher übergeben.</small></label>`}<label>Rolle<select name="role"><option value="teacher" ${x?.role==='teacher'?'selected':''}>Lehrkraft</option><option value="leadership" ${x?.role==='leadership'?'selected':''}>Schulleitung</option><option value="admin" ${x?.role==='admin'?'selected':''}>Administrator</option></select></label>${x?`<label class="checkbox-label"><input name="active" type="checkbox" ${x.active?'checked':''}> Konto aktiv</label>`:''}<button class="primary full">${x?'Änderungen speichern':'Benutzer anlegen'}</button></form>`);$('#create-user').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const body=Object.fromEntries(fd);if(x)body.active=fd.has('active');try{await api(x?`/admin/users/${x.id}`:'/admin/users',{method:x?'PUT':'POST',body:JSON.stringify(body)});closeDialog();adminPage(v);notify(x?'Benutzer aktualisiert.':'Benutzer angelegt.')}catch(e){notify(e.message)}}}$('#add-user').onclick=()=>userDialog();document.querySelectorAll('[data-edit-user]').forEach(b=>b.onclick=()=>userDialog(users.find(x=>x.id===b.dataset.editUser)))}

async function auditPage(v){const logs=await api('/audit');v.innerHTML=title('Audit-Log','Nachvollziehbare Aktionen und Anwesenheitsänderungen','')+`<section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Zeit</th><th>Benutzer</th><th>Aktion</th><th>Datensatz</th><th>Änderung</th></tr></thead><tbody>${logs.map(x=>`<tr><td>${fmt(x.created_at.slice(0,10))} ${x.created_at.slice(11,16)}</td><td>${esc(x.user_name||'System')}</td><td><span class="class-tag">${esc(x.action)}</span></td><td>${esc(x.entity)} · ${esc(x.entity_id.slice(0,12))}</td><td class="muted">${esc(x.new_value||'—')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Noch keine protokollierten Änderungen.</td></tr>'}</tbody></table></div></section>`}
function dialog(titleText,body){const old=$('#modal');old?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><section class="modal"><header><h2>${titleText}</h2><button id="modal-close" aria-label="Schließen">×</button></header><div>${body}</div></section></div>`);$('#modal-close').onclick=closeDialog;$('#modal').onclick=e=>{if(e.target.id==='modal')closeDialog()}}
function closeDialog(){$('#modal')?.remove()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b){go(b.dataset.page);$('.sidebar')?.classList.remove('open')}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search')?.focus()}if(e.key==='Escape'){closeDialog();if($('#search-results'))$('#search-results').hidden=true}});init().catch(e=>{console.error(e);$('#app').innerHTML=`<section class="error-screen"><h1>SchoolPresence konnte nicht geladen werden</h1><p>${esc(e.message)}</p><button class="primary" onclick="location.reload()">Erneut versuchen</button></section>`});
